from typing import List

def find_kth_smallest(list1: List[int], list2: List[int], k: int) -> int:
    """
    Finds the kth smallest element in the union of two sorted lists.

    Args:
    list1: A sorted list of integers.
    list2: Another sorted list of integers.
    k: The kth position to find the smallest element for (1-indexed).

    Returns:
    The kth smallest element in the union of list1 and list2.
    """
    def find_kth(list1, list2, k):
        if not list1:
            return list2[k-1]
        if not list2:
            return list1[k-1]
        if k == 1:
            return min(list1[0], list2[0])

        mid1 = len(list1) // 2
        mid2 = len(list2) // 2

        if mid1 + mid2 < k:
            if list1[mid1] > list2[mid2]:
                return find_kth(list1, list2[mid2+1:], k-mid2-1)
            else:
                return find_kth(list1[mid1+1:], list2, k-mid1-1)
        else:
            if list1[mid1] > list2[mid2]:
                return find_kth(list1[:mid1], list2, k)
            else:
                return find_kth(list1, list2[:mid2], k)

    return find_kth(list1, list2, k)

